effect.shader:
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }

void main() {
    float linha = floor(acScreenNorm.y * lines);
    float j = (hash(vec2(linha, floor(acTime * 30.0))) - 0.5) * 2.0 * jitter;
    vec2 uv = acScreenNorm + vec2(j, 0.0);

    // sangria horizontal: média de várias amostras laterais
    vec3 bl = vec3(0.0);
    for (int i = -4; i <= 4; i++) {
        float w = 1.0 - abs(float(i)) / 4.0;
        bl += texture(inputImg, uv + vec2(float(i) * bleed * 0.25, 0.0)).rgb * w;
    }
    bl /= 5.0;

    // separação RG / B
    float r = texture(inputImg, uv + vec2(chroma, 0.0)).r;
    float g = bl.g;
    float b = texture(inputImg, uv - vec2(chroma, 0.0)).b;

    // linhas rolando
    float roll = 0.5 + 0.5 * sin(acScreenNorm.y * lines * 0.5 + acTime * rollSpeed * 10.0);
    vec3 cor = vec3(r, g, b) * mix(0.85, 1.15, roll);

    float a = texture(inputImg, uv).a;
    fragColor = vec4(cor, a);
}
